#!/usr/bin/env bash
# Generated by cloudcc. Builds a deployment artefact for each execution unit.
#
# Pulumi does not install dependencies for you, so this runs before
# `pulumi up`. `cloudcc deploy` invokes it automatically.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$here"

build="build"
rm -rf "$build"
mkdir -p "$build"

echo "packaging execution unit api"
unit_build="$build/api"
mkdir -p "$unit_build"
cp -R "api/." "$unit_build/"

if [ -s "api/requirements.txt" ]; then
  uv pip install \
    --quiet \
    --target "$unit_build" \
    --python-version "3.12" \
    --only-binary=:all: \
    -r "api/requirements.txt"
fi

# Deterministic zip: fixed timestamps and sorted entries, so an unchanged unit
# produces a byte-identical artefact and Pulumi sees no diff.
find "$unit_build" -name '__pycache__' -type d -prune -exec rm -rf {} +
find "$unit_build" -exec touch -t 198001010000 {} +
( cd "$unit_build" && find . -type f | LC_ALL=C sort | zip -q -X -@ "../api.zip" )
echo "  wrote $build/api.zip"

echo "packaging execution unit worker"
unit_build="$build/worker"
mkdir -p "$unit_build"
cp -R "worker/." "$unit_build/"

if [ -s "worker/requirements.txt" ]; then
  uv pip install \
    --quiet \
    --target "$unit_build" \
    --python-version "3.12" \
    --only-binary=:all: \
    -r "worker/requirements.txt"
fi

# Deterministic zip: fixed timestamps and sorted entries, so an unchanged unit
# produces a byte-identical artefact and Pulumi sees no diff.
find "$unit_build" -name '__pycache__' -type d -prune -exec rm -rf {} +
find "$unit_build" -exec touch -t 198001010000 {} +
( cd "$unit_build" && find . -type f | LC_ALL=C sort | zip -q -X -@ "../worker.zip" )
echo "  wrote $build/worker.zip"

echo "packaging complete"
